async function cardPages(cards, sub){
  const PER = 2, pages = [];
  for (let p = 0; p < cards.length; p += PER) {
    const { cv, x } = await pageBase(sub);
    pages.push(cv);
    const part = cards.slice(p, p + PER);
    const X0 = 60, W = PG_W - 120, Y0 = 186, RH = 540, GAP = 20, PWb = 520;
    for (let i = 0; i < part.length; i++) {
      const c = part[i], Y = Y0 + i * (RH + GAP);
      x.save(); x.shadowColor = 'rgba(0,0,0,.5)'; x.shadowBlur = 26; x.shadowOffsetY = 10;
      rrect(x, X0, Y, W, RH, 26); x.fillStyle = '#1a1f27'; x.fill(); x.restore();
      x.save(); rrect(x, X0, Y, W, RH, 26); x.clip();
      const ig = x.createLinearGradient(0, Y, 0, Y + RH); ig.addColorStop(0, '#222831'); ig.addColorStop(1, '#10141a');
      x.fillStyle = ig; x.fillRect(X0, Y, PWb, RH);
      const img = await loadImg(photo(c.code, c.color));
      if (img) {
        const s = Math.min((PWb - 12) / img.width, (RH - 12) / img.height), w = img.width * s, h = img.height * s;
        x.drawImage(img, X0 + (PWb - w) / 2, Y + (RH - h) / 2, w, h);
      } else {
        x.fillStyle = '#8b95a5'; x.font = '700 40px ' + PG_F; x.textAlign = 'center'; x.textBaseline = 'middle';
        x.fillText(c.code || '—', X0 + PWb / 2, Y + RH / 2); x.textAlign = 'left';
      }
      x.fillStyle = '#e3262f'; x.fillRect(X0 + PWb, Y, 5, RH);
      x.restore();
      x.save(); rrect(x, X0, Y, W, RH, 26); x.lineWidth = 2; x.strokeStyle = 'rgba(255,255,255,.08)'; x.stroke(); x.restore();
      const IX = X0 + PWb + 30, IW = W - PWb - 30 - 26;
      x.textBaseline = 'middle';
      x.font = '800 40px ' + PG_F; x.fillStyle = '#ffffff';
      x.fillText(c.code || '', IX, Y + 52);
      if (c.num) { x.textAlign = 'right'; x.font = '700 26px ' + PG_F; x.fillStyle = '#8b95a5'; x.fillText(String(c.num), IX + IW, Y + 52); x.textAlign = 'left'; }
      const nm = c.code ? productName(c.code) : c.name;
      x.font = '700 26px ' + PG_F; x.fillStyle = '#c9ced8';
      x.fillText(fitText(x, nm, IW), IX, Y + 96);
      const TH = 112, g = 14, HW = (IW - g) / 2;
      const tile = (TX, TY, TW, lab, val, dot) => {
        rrect(x, TX, TY, TW, TH, 18); x.fillStyle = 'rgba(255,255,255,.05)'; x.fill();
        x.lineWidth = 1.5; x.strokeStyle = 'rgba(255,255,255,.08)'; x.stroke();
        x.font = '800 18px ' + PG_F; x.fillStyle = '#e3262f'; x.fillText(lab, TX + 20, TY + 28);
        let vx = TX + 20;
        if (dot) { x.beginPath(); x.arc(vx + 14, TY + 76, 14, 0, Math.PI * 2); x.fillStyle = dot; x.fill(); x.lineWidth = 3; x.strokeStyle = 'rgba(255,255,255,.9)'; x.stroke(); vx += 40; }
        const room = TW - (vx - TX) - 16;
        let fs = 44; x.font = '800 ' + fs + 'px ' + PG_F;
        while (fs > 24 && x.measureText(String(val)).width > room) { fs -= 2; x.font = '800 ' + fs + 'px ' + PG_F; }
        x.fillStyle = '#ffffff';
        x.fillText(fitText(x, val, room), vx, TY + 76);
      };
      const T0 = Y + 140;
      tile(IX, T0, IW, 'COLOR', EN_COLOR[c.color] || c.color || '-', DOT_COLOR[c.color]);
      tile(IX, T0 + TH + g, HW, 'SIZE', c.size || '-');
      tile(IX + HW + g, T0 + TH + g, HW, 'QUANTITY', String(Number(c.qty) || 1));
      tile(IX, T0 + (TH + g) * 2, IW, 'SURNAME', c.print || '-');
    }
  }
  return pages;
}
